-- WordRecall.json (DRAFT, not yet reviewed)
UPDATE task_types SET parameter_schema = '{"reviewed":false,"schema":{"type":"object","title":"Word Recall parameters","required":["WordList","FolderName","FileExtension","NBlocks","BListFlag","RecallType","RecallDuration","TimePerWord","DelayedRecallFlag","ShowWelcome","ShowThankYou","ShowInstructions","AskForNotes"],"properties":{"DelayedRecallFlag":{"type":"boolean","title":"Delayed recall session","description":"Yes: this is the delayed-recall part. No words are presented; the participant sees the delayed-recall instructions and recalls List A once. All presentation settings below are then ignored. No: an immediate session with learning trials.","default":false},"WordList":{"type":"string","title":"Word list","description":"Which words are used. The page loads the list named <language>_<Word list> from InstructionsAndStimuli/Stimuli/WordRecall_Lists.js, and the audio from assets/SoundFiles/Words/<Word list>/<language>/<Audio folder>.","oneOf":[{"const":"RAVLT","title":"RAVLT (Rey Auditory Verbal Learning Test): English and French, with audio"},{"const":"CERAD","title":"CERAD: English, with audio"},{"const":"Hopkins","title":"Hopkins (HVLT): English, with audio"},{"const":"FaCE","title":"FaCE version A: English, with audio"},{"const":"Demo","title":"Demo: English, with audio"},{"const":"FaCE_VerB","title":"FaCE version B: English list, no audio folder (visual only)"},{"const":"FaCE_Training","title":"FaCE training: English list, no audio folder (visual only)"},{"const":"RAVLTSHORT","title":"RAVLT short: English list, no audio folder (visual only)"},{"const":"Test","title":"Test list: English list, no audio folder (visual only)"},{"const":"EN_FaCE_Training","title":"EN_FaCE_Training: CHECK: looks up EN_EN_FaCE_Training, which doesn''t exist (probably meant FaCE_Training)"},{"const":"EN_FaCE_VerB","title":"EN_FaCE_VerB: CHECK: looks up EN_EN_FaCE_VerB, which doesn''t exist (probably meant FaCE_VerB)"},{"const":"EN_Demo","title":"EN_Demo: CHECK: looks up EN_EN_Demo, which doesn''t exist (probably meant Demo)"}],"default":"RAVLT"},"FolderName":{"type":"string","title":"Audio folder (voice)","description":"Subfolder of the word list''s audio holding one recording per word, so a different voice can be used without changing the list. Every list currently has only ''Set001/''. Keep the trailing slash.","default":"Set001/"},"FileExtension":{"type":"string","title":"Audio file extension","description":"Extension of the word audio files, including the dot. All existing word audio is .wav.","default":".wav"},"NBlocks":{"type":"integer","title":"Learning trials","description":"How many times List A is presented and recalled in an immediate session (RAVLT standard: 5). Ignored in a delayed session.","minimum":1,"maximum":10,"default":5},"AudioPresentation":{"type":"boolean","title":"Speak the words","description":"Play each word''s audio. If Show the words is also Yes, the word is shown on screen while it plays. CHECK: if both this and Show the words are No, no words are presented at all.","default":true},"VisualPresentation":{"type":"boolean","title":"Show the words","description":"Show each word on screen. With Speak the words = No, the words are shown silently. CHECK: List B is only ever presented as audio, so a visual-only session with List B shows no List B words.","default":true},"TimePerWord":{"type":"integer","title":"Time per word (ms)","description":"How long each word is presented. A 200 ms fixation cross comes before each word (fixed in config/WordRecall_Setup.js). With audio, allow enough time for the recording to finish (existing audio sets use 500-1500 ms).","minimum":100,"maximum":10000,"multipleOf":50,"default":1500},"BListFlag":{"type":"boolean","title":"Include List B (interference list)","description":"After the learning trials: present List B once and recall it, then ask for List A again without re-presenting it (the standard RAVLT interference and short-delay recall).","default":false},"WordListOrder":{"title":"Word order","description":"Optional. Positions of the words in the list, starting at 0. Leave empty to present the words in list order every trial.","anyOf":[{"title":"Different order for each learning trial","type":"array","items":{"type":"array","items":{"type":"integer","minimum":0}}},{"title":"Same order for every learning trial","type":"array","items":{"type":"integer","minimum":0}}]},"RecallType":{"type":"string","title":"Recall type","description":"How recalled words are collected.","oneOf":[{"const":"Spoken","title":"Spoken: the participant says the words; recorded, with speech recognition (microphone check first)"},{"const":"Manual","title":"Manual: recalled words are picked from the list on screen, plus boxes for words not on the list"}],"default":"Spoken"},"RecallDuration":{"type":"integer","title":"Recall time (s)","description":"How long each recall period lasts. The countdown clock starts at this value.","minimum":10,"maximum":600,"default":60},"DelayBeforeShowingDoneButton":{"type":"integer","title":"Seconds before the Done button appears","description":"The participant can end a recall period early once this many seconds have passed. Must be less than Recall time. CHECK: if this is missing, the Done button never appears and recall always runs the full time.","minimum":0,"maximum":600,"default":8},"ShowInstructions":{"type":"boolean","title":"Show instructions","description":"Show the instruction pages from the instruction set before each part of the task.","default":true},"InstructionsSpoken":{"type":"boolean","title":"Speak the instructions","description":"Play an audio file for each instruction page, with a progress bar. Needs the Instructions NN audio and time lists below for every instruction block used.","default":false},"Instructions01Audio":{"type":"array","title":"Instructions 01 audio (before learning trial 1)","description":"One audio file per instruction page, e.g. assets/SoundFiles/Instructions/WordRecall_Instructions01A.wav. Only used when Speak the instructions is Yes.","items":{"type":"string"}},"Instructions01Time":{"title":"Instructions 01 times (ms)","description":"How long each Instructions 01 page stays up while its audio plays, one number per page in milliseconds, separated by commas, e.g. 10000, 8000. One existing set (DemoENManual) has a single number here; saving it turns that into a one-item list, which is what the task expects."},"Instructions02Audio":{"type":"array","title":"Instructions 02 audio (before learning trials 2 and up)","items":{"type":"string"}},"Instructions02Time":{"type":"array","title":"Instructions 02 times (ms)","items":{"type":"integer","minimum":0}},"Instructions03Audio":{"type":"array","title":"Instructions 03 audio (before List B)","items":{"type":"string"}},"Instructions03Time":{"type":"array","title":"Instructions 03 times (ms)","items":{"type":"integer","minimum":0}},"Instructions04Audio":{"type":"array","title":"Instructions 04 audio (before recalling List A after List B)","items":{"type":"string"}},"Instructions04Time":{"type":"array","title":"Instructions 04 times (ms)","items":{"type":"integer","minimum":0}},"Instructions05Audio":{"type":"array","title":"Instructions 05 audio (before the first recall)","description":"CHECK: no existing set defines Instructions 05 audio/times, although the code plays them when Speak the instructions is Yes.","items":{"type":"string"}},"Instructions05Time":{"type":"array","title":"Instructions 05 times (ms)","items":{"type":"integer","minimum":0}},"ShowWelcome":{"type":"boolean","title":"Show welcome page","description":"Show the welcome page (from the instruction set) before the task.","default":true},"WelcomeSpoken":{"type":"boolean","title":"Speak the welcome","description":"Only applies when the welcome is shown: play the welcome audio with a Repeat button and a 4 s progress bar.","default":false},"WelcomeAudio":{"type":"string","title":"Welcome audio file","description":"Only used when Speak the welcome is Yes.","default":"assets/SoundFiles/Instructions/Welcome_WordRecall.wav"},"AskForNotes":{"type":"boolean","title":"Ask for examiner notes","description":"At the end, show a free-text box for notes about the session.","default":false},"ShowThankYou":{"type":"boolean","title":"Show thank-you page","description":"Show the thank-you page (from the instruction set) at the end.","default":true},"RecordAUDIO":{"type":"boolean","title":"Record audio","description":"CHECK: has no effect. No Word Recall code reads this setting; spoken recall is always recorded, and manual recall never is.","default":true}},"additionalProperties":true},"uiSchema":{"ui:order":["DelayedRecallFlag","WordList","FolderName","FileExtension","NBlocks","AudioPresentation","VisualPresentation","TimePerWord","BListFlag","WordListOrder","RecallType","RecallDuration","DelayBeforeShowingDoneButton","ShowInstructions","InstructionsSpoken","Instructions01Audio","Instructions01Time","Instructions02Audio","Instructions02Time","Instructions03Audio","Instructions03Time","Instructions04Audio","Instructions04Time","Instructions05Audio","Instructions05Time","ShowWelcome","WelcomeSpoken","WelcomeAudio","AskForNotes","ShowThankYou","RecordAUDIO","*"],"DelayedRecallFlag":{"ui:widget":"radio"},"AudioPresentation":{"ui:widget":"radio"},"VisualPresentation":{"ui:widget":"radio"},"BListFlag":{"ui:widget":"radio"},"ShowInstructions":{"ui:widget":"radio"},"InstructionsSpoken":{"ui:widget":"radio"},"Instructions01Time":{"ui:field":"numberList"},"ShowWelcome":{"ui:widget":"radio"},"WelcomeSpoken":{"ui:widget":"radio"},"AskForNotes":{"ui:widget":"radio"},"ShowThankYou":{"ui:widget":"radio"},"RecordAUDIO":{"ui:widget":"radio"}}}'
WHERE task_name IN ('Word Recall', 'Word Recall Database');

