default":false,"description":"Show the thank-you page (from the instruction set) at the end."},"ShowInstructions":{"type":"boolean","title":"Show instructions","default":true,"description":"Show the instruction pages (from the instruction set) before the task."},"InstructionsSpoken":{"type":"boolean","title":"Speak the instructions","default":false,"description":"Play an audio file with each instruction page, with a progress bar. Needs the ''Instructions NN audio files'' and ''page times'' lists below for every instruction block the task shows."},"AskForNotes":{"type":"boolean","title":"Ask for examiner notes","default":false,"description":"At the end, show a free-text box for notes about the session."},"RecordAUDIO":{"type":"boolean","title":"Record audio (not used)","default":true,"description":"Not used by the task: no code reads this setting. Kept so existing sets open unchanged. Spoken responses are always recorded and manual responses never are."}},"additionalProperties":true},"uiSchema":{"AudioPresentation":{"ui:widget":"radio"},"VisualPresentation":{"ui:widget":"radio"},"ShowWelcome":{"ui:widget":"radio"},"WelcomeSpoken":{"ui:widget":"radio"},"ShowThankYou":{"ui:widget":"radio"},"ShowInstructions":{"ui:widget":"radio"},"InstructionsSpoken":{"ui:widget":"radio"},"AskForNotes":{"ui:widget":"radio"},"RecordAUDIO":{"ui:widget":"radio"},"ui:order":["WordList","FolderName","FileExtension","AudioPresentation","VisualPresentation","RecallType","RecogDuration","ShowInstructions","InstructionsSpoken","ShowWelcome","WelcomeSpoken","AskForNotes","ShowThankYou","RecordAUDIO","*"]}}'
